import 'package:flutter/material.dart'; import 'package:url_launcher/url_launcher.dart'; import '../models/report.dart'; import '../widgets/status_badge.dart';
class ReportDetailsScreen extends StatelessWidget { const ReportDetailsScreen({required this.report,super.key});final IncidentReport report; @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:Text(report.reportId)),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(report.incidentType,style:Theme.of(context).textTheme.headlineSmall),const SizedBox(height:8),StatusBadge(report.status),const SizedBox(height:20),Text(report.description),const Divider(height:32),Text('Submitted: ${report.createdLabel}'),if(report.receivedAt!=null)Text('Received: ${report.receivedAt!.toLocal()}'),if(report.deliveryTime!=null)Text('Alert delivery time: ${report.deliveryTime}'),Text('Latitude: ${report.latitude.toStringAsFixed(6)}'),Text('Longitude: ${report.longitude.toStringAsFixed(6)}'),if(report.locationAccuracy!=null)Text('GPS accuracy reported by device: ±${report.locationAccuracy!.toStringAsFixed(1)} m'),const SizedBox(height:12),OutlinedButton.icon(onPressed:()=>launchUrl(Uri.parse('https://www.openstreetmap.org/?mlat=${report.latitude}&mlon=${report.longitude}#map=18/${report.latitude}/${report.longitude}'),mode:LaunchMode.externalApplication),icon:const Icon(Icons.map_outlined),label:const Text('Open location in map'))]));}
